    restore(after.玩家, '性别', '男性', '/玩家/性别');
    if (before.系统.结构版本 === 4) {
      // false→true 是明确本局觉醒的事实更新，由更新规则约束语义；代码不从战斗或旧境界猜测。
      // 普通主回复不能抹掉已确认觉醒；经绑定的副校正可用原生布尔值修正误记。
      const awakened = before.玩家.魔人觉醒 === true;
      if (!flexible && awakened || typeof after.玩家.魔人觉醒 !== 'boolean') {
