Hiragino Sans GB\", \"Microsoft YaHei UI\", \"Yu Gothic UI\", \"Noto Sans CJK SC\", sans-serif;\n  --font-num: \"SF Pro Text\", \"Segoe UI\", Roboto, tabular-nums;\n  --surface: #111520;\n  --screen: #0a0d14;\n  --card: #161c2b;\n  --card2: #1e2638;\n  --ink: #f8fafc;\n  --ink2: #cbd5e1;\n  --muted: #718096;\n  --hair: rgba(255, 255, 255, 0.09);\n  --ring: rgba(239, 68, 68, 0.35);\n  --crimson: #ef4444;\n  --crimson-glow: rgba(239, 68, 68, 0.45);\n  --hagun-gold: #f59e0b;\n  --lime: #10b981;\n  --sky: #38bdf8;\n  --shadow: 0 4px 16px rgba(0, 0, 0, 0.5), 0 1px 3px rgba(0, 0, 0, 0.3);\n  --press: rgba(255, 255, 255, 0.06);\n}\n\n:root[data-rk-theme=\"light\"] {\n  color-scheme: light;\n  --surface: #f8fafc;\n  --screen: #f1f5f9;\n  --card: #ffffff;\n  --card2: #e2e8f0;\n  --ink: #0f172a;\n  --ink2: #334155;\n  --muted: #64748b;\n  --hair: rgba(0, 0, 0, 0.08);\n  --ring: rgba(239, 68, 68, 0.3);\n  --crimson: #dc2626;\n  --crimson-glow: rgba(220, 38, 38, 0.25);\n  --hagun-gold: #d97706;\n  --lime: #059669;\n  --sky: #0284c7;\n  --shadow: 0 4px 16px rgba(0, 0, 0, 0.08), 0 1px 3px rgba(0, 0, 0, 0.05);\n  --press: rgba(0, 0, 0, 0.04);\n}\n\n* { box-sizing: border-box; }\nhtml, body {\n  margin: 0;\n  padding: 0;\n  height: 100%;\n  width: 100%;\n  font-family: var(--font-ui);\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n  text-rendering: optimizeLegibility;\n}\n\nbody {\n  background: var(--screen);\n  color: var(--ink);\n  overflow: hidden;\n  display: flex;\n  flex-direction: column;\n  user-select: none;\n}\n\n.num { font-family: var(--font-num); }\nbutton {\n  font-family: inherit;\n  color: inherit;\n  background: none;\n  border: 0;\n  cursor: pointer;\n  padding: 0;\n}\n\n/* 顶栏状态栏 (Hagun Status) */\n#sys {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 14px 6px;\n  font-size: 11px;\n  color: var(--ink2);\n  flex: none;\n  background: rgba(10, 13, 20, 0.95);\n  border-bottom: 1px solid var(--hair);\n  position: relative;\n  z-index: 10;\n}\n#sys .sys-brand {\n  font-weight: 800;\n  font-size: 10.5px;\n  letter-spacing: 0.5px;\n  color: var(--crimson);\n  display: flex;\n  align-items: center;\n  gap: 4px;\n}\n#sys .sys-brand::before {\n  content: '';\n  display: inline-block;\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: var(--crimson);\n  box-shadow: 0 0 8px var(--crimson);\n}\n#sys .sys-clk {\n  font-size: 13px;\n  font-weight: 700;\n  color: var(--ink);\n  margin-left: auto;\n}\n#sys .sys-icons {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 12px;\n}\n\n/* 视口堆叠 */\n#stack {\n  flex: 1;\n  position: relative;\n  overflow: hidden;\n}\n.scr {\n  position: absolute;\n  inset: 0;\n  display: flex;\n  flex-direction: column;\n  background: var(--screen);\n  transform: translateX(100%);\n  transition: transform 0.22s cubic-bezier(0.16, 1, 0.3, 1);\n  overflow: hidden;\n  pointer-events: none;\n  visibility: hidden;\n}\n.scr.on {\n  transform: none;\n  pointer-events: auto;\n  visibility: visible;\n}\n.scr.under {\n  transform: translateX(-20%);\n  opacity: 0.7;\n  pointer-events: none;\n  visibility: visible;\n}\n#scr-home { transform: none; pointer-events: auto; visibility: visible; }\n\n.apphead {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 10px 14px;\n  flex: none;\n  background: var(--surface);\n  border-bottom: 1px solid var(--hair);\n  box-shadow: 0 2px 8px rgba(0,0,0,0.25);\n  z-index: 5;\n}\n.apphead .back {\n  width: 32px;\n  height: 32px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 18px;\n  color: var(--ink2);\n  border-radius: 8px;\n}\n.apphead .back:hover { background: var(--press); }\n.apphead .t {\n  font-weight: 700;\n  font-size: 15px;\n  flex: 1;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.apphead .sub {\n  font-size: 11px;\n  color: var(--muted);\n  margin-left: 4px;\n}\n.apphead .act {\n  margin-left: auto;\n  font-size: 12.5px;\n  color: var(--ink2);\n}\n\n.body {\n  flex: 1;\n  overflow-y: auto;\n  overflow-x: hidden;\n  overscroll-behavior: contain;\n  padding-bottom: 12px;\n}\n\n/* 底部 Homebar 导航 */\n#homebar {\n  flex: none;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  padding: 6px 0 8px;\n  background: var(--surface);\n  border-top: 1px solid var(--hair);\n}\n#homebar button {\n  width: 120px;\n  height: 24px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n#homebar i {\n  display: block;\n  width: 64px;\n  height: 4px;\n  border-radius: 2px;\n  background: var(--muted);\n  opacity: 0.6;\n  transition: opacity 0.15s;\n}\n#homebar button:hover i { opacity: 1; background: var(--crimson); }\n\n/* ===== 首页与二次元学生证 (Blazer License Card) ===== */\n.home-wallpaper {\n  position: absolute;\n  inset: 0;\n  background: radial-gradient(circle at 80% 10%, rgba(239, 68, 68, 0.18) 0%, transparent 60%),\n              radial-gradient(circle at 10% 90%, rgba(56, 189, 248, 0.1) 0%, transparent 50%),\n              linear-gradient(180deg, #10141f 0%, #090c13 100%);\n  z-index: 0;\n}\n.home-content {\n  position: relative;\n  z-index: 1;\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n}\n\n/* 伐刀者身份磁卡 Widget */\n.blazer-license-card {\n  margin: 12px 14px 6px;\n  padding: 14px;\n  border-radius: 18px;\n  background: linear-gradient(145deg, rgba(26, 32, 48, 0.85) 0%, rgba(15, 20, 31, 0.9) 100%);\n  border: 1px solid rgba(239, 68, 68, 0.35);\n  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.12);\n  backdrop-filter: blur(12px);\n  -webkit-backdrop-filter: blur(12px);\n  cursor: pointer;\n  transition: transform 0.15s, border-color 0.15s;\n}\n.blazer-license-card:active { transform: scale(0.98); }\n.blazer-license-card:hover { border-color: rgba(239, 68, 68, 0.65); }\n\n.card-top {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n.card-avatar {\n  width: 46px;\n  height: 46px;\n  border-radius: 12px;\n  background: linear-gradient(135deg, #ef4444 0%, #b91c1c 100%);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-weight: 800;\n  font-size: 18px;\n  color: #fff;\n  box-shadow: 0 4px 12px rgba(239, 68, 68, 0.4);\n  flex: none;\n  overflow: hidden;\n}\n.card-avatar img { width: 100%; height: 100%; object-fit: cover; }\n.card-info { flex: 1; min-width: 0; }\n.card-name-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.card-name {\n  font-size: 16px;\n  font-weight: 800;\n  color: var(--ink);\n  letter-spacing: 0.2px;\n}\n.card-class {\n  font-size: 11px;\n  color: var(--muted);\n}\n.card-rank-badge {\n  margin-left: auto;\n  padding: 3px 8px;\n  border-radius: 8px;\n  background: linear-gradient(135deg, rgba(239, 68, 68, 0.2) 0%, rgba(185, 28, 28, 0.4) 100%);\n  border: 1px solid rgba(239, 68, 68, 0.55);\n  color: #fca5a5;\n  font-weight: 800;\n  font-size: 12px;\n  text-shadow: 0 0 6px rgba(239, 68, 68, 0.5);\n}\n\n.card-device-row {\n  margin-top: 8px;\n  padding-top: 8px;\n  border-top: 1px solid var(--hair);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  font-size: 12px;\n}\n.card-device-name {\n  color: var(--sky);\n  font-weight: 600;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.card-noble-art {\n  font-size: 11px;\n  color: var(--hagun-gold);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  max-width: 45%;\n}\n\n/* 六维药丸指示行 */\n.card-axes-pills {\n  margin-top: 8px;\n  display: flex;\n  gap: 4px;\n  justify-content: space-between;\n}\n.axis-pill {\n  flex: 1;\n  text-align: center;\n  padding: 3px 0;\n  border-radius: 6px;\n  background: rgba(0, 0, 0, 0.35);\n  border: 1px solid var(--hair);\n  font-size: 10px;\n  color: var(--muted);\n}\n.axis-pill b {\n  color: var(--ink);\n  margin-left: 2px;\n  font-size: 11px;\n}\n.axis-pill.rank-A b { color: #f59e0b; font-weight: 800; text-shadow: 0 0 6px rgba(245,158,11,0.5); }\n.axis-pill.rank-B b { color: #38bdf8; font-weight: 700; }\n.axis-pill.rank-C b { color: #10b981; font-weight: 600; }\n.axis-pill.rank-D b { color: #cbd5e1; }\n.axis-pill.rank-E b { color: #94a3b8; }\n.axis-pill.rank-F b { color: #ef4444; font-weight: 800; }\n\n/* 8 大战术 App 启动器网格 (Anime App Grid) */\n.app-grid {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 12px 6px;\n  padding: 14px 12px;\n  flex: 1;\n}\n.app-btn {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 6px;\n  cursor: pointer;\n  position: relative;\n}\n.app-btn:active { transform: scale(0.93); }\n.app-icon-wrap {\n  width: 52px;\n  height: 52px;\n  border-radius: 16px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.45);\n  font-size: 24px;\n  color: #fff;\n  position: relative;\n  border: 1px solid rgba(255, 255, 255, 0.12);\n  transition: box-shadow 0.15s, transform 0.15s;\n}\n.app-btn:hover .app-icon-wrap { box-shadow: 0 6px 20px rgba(239, 68, 68, 0.35); }\n\n/* 应用图标渐变色系 */\n.app-blazer .app-icon-wrap { background: linear-gradient(135deg, #ef4444 0%, #991b1b 100%); }\n.app-lime .app-icon-wrap   { background: linear-gradient(135deg, #10b981 0%, #065f46 100%); }\n.app-moments .app-icon-wrap{ background: linear-gradient(135deg, #ec4899 0%, #9d174d 100%); }\n.app-bbs .app-icon-wrap    { background: linear-gradient(135deg, #38bdf8 0%, #0369a1 100%); }\n.app-schedule .app-icon-wrap{ background: linear-gradient(135deg, #8b5cf6 0%, #5b21b6 100%); }\n.app-gallery .app-icon-wrap { background: linear-gradient(135deg, #f59e0b 0%, #b45309 100%); }\n.app-world .app-icon-wrap   { background: linear-gradient(135deg, #06b6d4 0%, #0e7490 100%); }\n.app-settings .app-icon-wrap{ background: linear-gradient(135deg, #64748b 0%, #334155 100%); }\n\n.app-name {\n  font-size: 11.5px;\n  font-weight: 600;\n  color: var(--ink2);\n  text-align: center;\n  letter-spacing: -0.2px;\n}\n.app-badge {\n  position: absolute;\n  top: -3px;\n  right: -3px;\n  min-width: 18px;\n  height: 18px;\n  border-radius: 9px;\n  background: var(--crimson);\n  color: #fff;\n  font-size: 10px;\n  font-weight: 800;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 0 4px;\n  border: 1.5px solid var(--screen);\n}\n\n/* ===== 通用卡片与列表 ===== */\n.card1 {\n  background: var(--card);\n  border-radius: 16px;\n  padding: 14px;\n  margin: 10px 14px;\n  border: 1px solid var(--hair);\n  box-shadow: var(--shadow);\n}\n.ct {\n  font-size: 11.5px;\n  font-weight: 700;\n  color: var(--muted);\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n  margin-bottom: 8px;\n}\n\n/* 选项卡 (Tabs) */\n.subtabs {\n  display: flex;\n  background: var(--surface);\n  border-bottom: 1px solid var(--hair);\n  padding: 0 8px;\n}\n.subtab {\n  flex: 1;\n  text-align: center;\n  padding: 10px 4px;\n  font-size: 12.5px;\n  font-weight: 600;\n  color: var(--muted);\n  border-bottom: 2px solid transparent;\n  cursor: pointer;\n}\n.subtab.on {\n  color: var(--crimson);\n  border-bottom-color: var(--crimson);\n}\n\n/* ===== SVG 六维雷达图 (Hexagonal Radar Chart) ===== */\n.radar-container {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  padding: 14px 0 6px;\n}\n.radar-svg {\n  width: 260px;\n  height: 240px;\n  overflow: visible;\n}\n.radar-polygon {\n  fill: rgba(239, 68, 68, 0.28);\n  stroke: #ef4444;\n  stroke-width: 2.2;\n  filter: drop-shadow(0 0 8px rgba(239, 68, 68, 0.6));\n}\n.radar-web {\n  fill: none;\n  stroke: rgba(255, 255, 255, 0.12);\n  stroke-width: 1;\n}\n.radar-web-spoke {\n  stroke: rgba(255, 255, 255, 0.14);\n  stroke-width: 1;\n  stroke-dasharray: 2 2;\n}\n.radar-point {\n  fill: #fff;\n  stroke: #ef4444;\n  stroke-width: 2;\n}\n.radar-label {\n  font-size: 11px;\n  font-weight: 700;\n  fill: var(--ink2);\n  text-anchor: middle;\n  dominant-baseline: middle;\n}\n.radar-rank-badge {\n  font-size: 11px;\n  font-weight: 800;\n  fill: #fca5a5;\n  text-anchor: middle;\n  dominant-baseline: middle;\n}\n\n/* 灵装绝技机制卡 */\n.noble-art-block {\n  margin-top: 10px;\n  padding: 10px 12px;\n  border-radius: 10px;\n  background: var(--card2);\n  border-left: 3px solid var(--crimson);\n}\n.noble-art-title {\n  font-size: 13px;\n  font-weight: 700;\n  color: var(--ink);\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n.noble-art-desc {\n  font-size: 12px;\n  color: var(--ink2);\n  margin-top: 4px;\n  line-height: 1.5;\n}\n\n/* 同伴名册与羁绊列表 */\n.roster-list {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding: 0 14px;\n}\n.roster-card {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 10px 12px;\n  background: var(--card);\n  border-radius: 14px;\n  border: 1px solid var(--hair);\n  cursor: pointer;\n}\n.roster-card:hover { background: var(--press); }\n.roster-ava {\n  width: 40px;\n  height: 40px;\n  border-radius: 10px;\n  background: linear-gradient(135deg, #38bdf8 0%, #0284c7 100%);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-weight: 700;\n  color: #fff;\n  flex: none;\n}\n.roster-info { flex: 1; min-width: 0; overflow-wrap: anywhere; }\n.roster-name-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n.roster-name { font-size: 13.5px; font-weight: 700; }\n.roster-rank {\n  font-size: 10px;\n  font-weight: 800;\n  padding: 1px 5px;\n  border-radius: 4px;\n  background: rgba(239, 68, 68, 0.2);\n  color: #fca5a5;\n}\n.roster-device {\n  font-size: 11px;\n  color: var(--muted);\n  margin-top: 2px;\n}\n\n/* 破军 LIME 聊天 */\n.lime-threads {\n  display: flex;\n  flex-direction: column;\n}\n.lime-row {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 12px 14px;\n  border-bottom: 1px solid var(--hair);\n  cursor: pointer;\n}\n.lime-row:hover { background: var(--press); }\n.lime-avatar {\n  width: 44px;\n  height: 44px;\n  border-radius: 14px;\n  background: var(--card2);\n  display: flex;\n  align-items: